    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided distinguishing exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "RCTs including hospitalized patients with objectively diagnosed SARS-CoV2 infection and comparing high-dose anticoagulation (experimental group) with low-dose anticoagulation (control group) were eligible. ... Sensitivity analyses were planned to compare the efficacy and safety of intermediate or therapeutic dose versus low-dose thromboprophylaxis, and of high-dose versus lowdose thromboprophylaxis in critically ill and non-critically ill COVID-19 patients. Critically ill patients included those admitted to ICU, patients requiring invasive mechanical ventilation, and patients with severe COVID-19 as defined by the study authors. All other patients were considered noncritically ill. We included a study in one of the subgroups above if more than 75% of patients in that study fulfilled these criteria.",
      "reason": "The review explicitly defines the groups used for synthesis (high-dose vs low-dose; intermediate vs therapeutic; critically ill vs non-critically ill) and links subgroup grouping rules (including the >75% rule) to the comparisons in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale is provided for notable eligibility restrictions (for example, no explanation is given for the language restriction or the chosen date range)."
    }
